1	export function checkImpeach(chunkText, context) {
2	  // Bracketed markers only — see engine/mechanisms/veto.mjs. "弹劾：某某"
3	  // ("impeach: so-and-so") appears in ordinary historical narration of a
4	  // censorate's duties, so the unbracketed form cannot be told apart from an
5	  // actual act of impeachment once office prose is captured.
6	  const text = String(chunkText ?? "");
7	  const match = text.match(/\[IMPEACH:\s*([^\]]+)\]/i) || text.match(/\[弹劾[:：]\s*([^\]]+)\]/i);
8	  if (match) {
9	    const target = match[1].trim();
10	    // To prevent infinite loops or spam, check if we already impeached this target recently
11	    if (!context.impeachments) context.impeachments = new Set();
12	    
13	    if (!context.impeachments.has(target)) {
14	      context.impeachments.add(target);
15	      console.error(`\n[v6-Mechanism] IMPEACHMENT DETECTED! Target: ${target}. Logging historical event.`);
16	      
17	      context.log.emit("impeach_triggered", { 
18	        target: target,
19	        reason: "Censorate or equivalent authority has issued a formal impeachment." 
20	      });
21	      
22	      return true;
23	    }
24	  }
25	  return false;
26	}
